void ApplyMigrations(AppDbContext db)
{
    // EF Core 9 breaking change: Migrate() now uses its own internal
    // transaction and cannot be called inside a user-started transaction.
    // Use the execution strategy to handle retries only.
    var strategy = db.Database.CreateExecutionStrategy();
    strategy.Execute(() =>
    {
        db.Database.Migrate();
    });
}

